style.css:
@-moz-document domain("youtube.com") {
/* Hide ads or unwanted sidebars */
  .ad-banner, #sidebar {
    display: none !important;
  }

  /* Custom background and text colors */
  body, ytd-app {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* Custom link colors */
  a {
    color: #bb86fc !important;
  }
}
